    /**
     * SelectTeam.on_start (selectTeam.py:18-27): the match-start stinger in
     * MUSIC_AUDIO_ZONE (scaled by the music slider), then the secondary bed
     * unless the mode is classic. Called on SelectTeam entry only, never for
     * the in-game ChangeTeam menu (MatchStartStingerGate).
     */
    void play_match_start_stinger() {
        if (!audio_started) {
            return;
        }
        const auto stinger = match_start_stinger(match_initial_info.classic);
        static_cast<void>(audio->play_named_one_shot(
            stinger.stem, {}, audio->music_volume(), true, 0.0F, 0.15F, true));
        if (stinger.start_secondary_bed) {
            start_secondary_selection_music();
        }
    }

    /**
     * Play one retail client-local cue: a random member of its numbered
     * group at a random pitch within its semitone bounds (media.play_pitched).
     * `head_relative` is for cues whose source is the local player.
     */
    bool play_retail_cue(const audio::RetailCue& cue,
                         audio::SoundPosition position,
                         bool head_relative,
                         std::uint32_t seed = 0U,
                         float gain = 1.0F,
                         bool protect = false) {
        if (!audio_started) {
            return false;
        }
        const auto stems = audio::sound_group_stems(cue.group);
        if (stems.empty()) {
            return false;
        }
        const auto draw = seed ^ static_cast<std::uint32_t>(latest_world_loop) ^
                          (++retail_cue_counter * 2654435761U);
        return audio->play_named_one_shot(
            stems[draw % stems.size()],
            position,
            gain,
            head_relative,
            0.0F,
            0.15F,
            protect,
            audio::retail_sound_pitch_ratio(
                cue.pitch_semitones[0U], cue.pitch_semitones[1U], draw));
    }

    /**
     * BUILD_ERROR_SOUND: 2D and unpitched, played by every placement tool
     * (blockTool, c4/dynamite/landmine/medPack weapons, prefabTool,
     * flareBlockTool, UGC tools) when a placement is refused.
     */
    void play_build_error() {
        static_cast<void>(play_retail_cue(audio::build_error_cue, {}, true));
    }

    /** GameScene.process_packet_kill_action banners, stingers and streaks. */
    void announce_kill_action(const network::KillActionPacket& kill,
                              const network::RemotePlayerReplica& victim,
                              const network::RemotePlayerReplica* killer) {
        if (!local_player_id.has_value()) {
            return;
        }
        KillAnnouncementInput input;
        input.local_is_killer = kill.killer_id == *local_player_id;
        input.local_is_victim = kill.player_id == *local_player_id;
        input.killer_is_victim = kill.killer_id == kill.player_id;
        input.killer_known = killer != nullptr;
        input.kill_count = kill.kill_count;
        input.domination = kill.domination;
        input.revenge = kill.revenge;
        input.victim_name = victim.name;
        input.killer_name = killer != nullptr ? killer->name : std::string{};
        static_cast<void>(running_local_kills.apply(input, kill.player_id, kill.killer_id));
        for (const auto& announcement : kill_action_announcements(input)) {
            game_hud.set_big_message(format_announcement(
                localized_text(announcement.string_id), announcement.parameter));
            if (!announcement.stinger.empty() && audio_started) {
                // media.play(<ks sound>) with no position: a 2D HUD cue.
                static_cast<void>(audio->play_named_one_shot(
                    announcement.stinger, {}, 1.0F, true, 0.0F, 0.15F, true));
            }
        }
    }

    void start_secondary_selection_music() {
        if (audio_started && !audio->play_secondary_menu_music()) {
            settings_warning =
                "secondary selection music could not start: " + std::string{audio->last_error()};
        }
    }

    [[nodiscard]] network::AosPlayScoreServiceConfig score_service_config() const {
        network::AosPlayScoreServiceConfig service;
        service.leaderboard_url = config.leaderboard_url;
        service.profile_url = config.player_profile_url;
        return service;
    }

    [[nodiscard]] std::vector<LeaderboardPersona>
    social_leaderboard_personas() const {
        std::vector<LeaderboardPersona> personas;
        if (social_client == nullptr) return personas;
        const auto social = social_client->snapshot();
        personas.reserve(social.friends.size());
        for (const auto& row : social.friends) {
            if (row.friendship_status != "accepted") continue;
            std::uint64_t account{};
            const auto first = row.legacy_id.data();
            const auto last = first + row.legacy_id.size();
            const auto parsed = std::from_chars(first, last, account);
            if (parsed.ec != std::errc{} || parsed.ptr != last || account == 0U) {
                continue;
            }
            const auto& name = row.nickname.empty() ? row.username : row.nickname;
            personas.push_back({account, name});
        }
        return personas;
    }

    void launch_leaderboard_request(LeaderboardRequest request) {
        pending_leaderboard_request.reset();
        const auto service = score_service_config();
        const auto player_name = config.player_name;
        const auto known_account = resolved_player_account_id;
        std::vector<std::uint64_t> friend_accounts;
        if (request.scope == LeaderboardScope::friends) {
            const auto personas = social_leaderboard_personas();
            friend_accounts.reserve(personas.size());
            for (const auto& persona : personas) {
                friend_accounts.push_back(persona.account_id);
            }
        }
        leaderboard_worker = std::async(
            std::launch::async,
            [request, service, player_name, known_account,
             friend_accounts = std::move(friend_accounts)]() mutable {
                auto account_id = known_account;
                std::optional<std::uint64_t> resolved;
                const auto scope = static_cast<network::AosPlayLeaderboardScope>(request.scope);
                if (scope != network::AosPlayLeaderboardScope::global && account_id == 0U) {
                    std::string error;
                    const auto found =
                        network::resolve_aosplay_account_id(service, player_name, error);
                    if (!found.has_value()) {
                        return LeaderboardOutcome{request, {{}, std::move(error)}, std::nullopt};
                    }
                    account_id = *found;
                    resolved = account_id;
                }
                auto result = network::fetch_aosplay_leaderboard(
                    service, static_cast<std::uint8_t>(request.type), scope, account_id,
                    friend_accounts);
                return LeaderboardOutcome{request, std::move(result), std::move(resolved)};
            });
    }

    void dispatch_leaderboard_request() {
        const auto request = leaderboard_menu.take_request();
        if (!request.has_value())
            return;
        if (leaderboard_worker.valid()) {
            // Only the newest selection matters. The model's generation token
            // rejects the in-flight response, while this slot coalesces rapid
            // selector clicks into one follow-up HTTP request.
            pending_leaderboard_request = *request;
            return;
        }
        launch_leaderboard_request(*request);
    }

    void pump_leaderboard_request() {
        using namespace std::chrono_literals;
        if (!leaderboard_worker.valid() ||
            leaderboard_worker.wait_for(0ms) != std::future_status::ready) {
            return;
        }
        auto outcome = leaderboard_worker.get();
        if (outcome.resolved_account_id.has_value()) {
            resolved_player_account_id = *outcome.resolved_account_id;
        }
        if (outcome.result) {
            auto rows = leaderboard_rows(outcome.request, outcome.result);
            const auto personas = social_leaderboard_personas();
            apply_retail_leaderboard_personas(
                rows, resolved_player_account_id, config.player_name, personas);
            static_cast<void>(leaderboard_menu.complete(
                outcome.request, std::move(rows)));
        } else {
            settings_warning = outcome.result.error;
            static_cast<void>(leaderboard_menu.fail(outcome.request));
        }
        if (pending_leaderboard_request.has_value()) {
            const auto pending = *pending_leaderboard_request;
            launch_leaderboard_request(pending);
        }
    }

    void dispatch_inventory_action(InventoryAction action) {
        if (action == InventoryAction::none) return;
        if (action == InventoryAction::creators) {
            if (!window.open_external_url("https://www.aosplay.net/creators/skin-packs"))
                inventory_menu.error = "The creator page could not be opened.";
            return;
        }
        if (inventory_fixture) return;
        if (!inventory_session) inventory_session = std::make_unique<InventorySession>(identity_service);
        inventory_session->start(inventory_menu, action);
    }

    [[nodiscard]] bool markup_inventory_active() const {
        return !boot_loading && screen()==FrontendScreen::player_profile &&
            player_profile_menu.selected_tab()==PlayerProfileTab::inventory && inventory_view;
    }

    void consume_inventory_view() {
        if (!inventory_view) return;
        dispatch_inventory_action(inventory_view->take_action());
        const auto route=inventory_view->take_navigation();
        if (route==0) { static_cast<void>(navigation.pop()); play_back(); }
        else if (route>=1 && route<=4) {
            static_cast<void>(player_profile_menu.select_tab(static_cast<PlayerProfileTab>(route-1)));
        }
        const auto sound=inventory_view->take_sound();
        if (sound==1) play_scroll();
        else if (sound==2 || sound==3) play_confirm();
    }

    void pump_inventory() {
        using namespace std::chrono_literals;
        if(skin_variant_preferences&&applied_skin_variant_revision!=skin_variant_preferences->revision()){
            applied_skin_variant_revision=skin_variant_preferences->revision();
            uploaded_sandbox_tool.reset();failed_scripted_skins.clear();scripted_skin_prewarm_signature.clear();
        }
        const auto before=inventory_menu.data.equipped;
        if (inventory_session) inventory_session->pump(inventory_menu);
        if (inventory_autoload && !inventory_fixture && !inventory_menu.busy) {
            dispatch_inventory_action(InventoryAction::refresh);
            if (inventory_menu.busy) inventory_autoload=false;
        }
        if (before!=inventory_menu.data.equipped) {
            uploaded_sandbox_tool.reset(); loaded_tutorial_arm_class.reset();
            uploaded_tool.reset();view_model_meshes_uploaded=false;failed_scripted_skins.clear();scripted_skin_prewarm_signature.clear();
            remote_class_model_cache.clear(); remote_weapon_model_cache.clear();
            remote_player_rigs.clear(); entity_model_cache.clear(); entity_part_slots.clear(); entity_part_appearances.clear();
            inventory_preload_pending.clear();
            for (const auto& item : inventory_menu.data.items) {
                if (item.owned && item.enabled && std::ranges::any_of(inventory_menu.data.equipped,
                    [&](const auto& slot) { return slot.second == item.id; }))
                    inventory_preload_pending.push_back(item);
            }
        }
        if (inventory_preload_worker.valid() && inventory_preload_worker.wait_for(0ms) == std::future_status::ready)
            inventory_preload_worker.get();
        if (!inventory_preload_worker.valid() && !inventory_preload_pending.empty()) {
            inventory_preload_worker=std::async(std::launch::async,
                [items=std::exchange(inventory_preload_pending, {}), root=config.asset_root] {
                    for (const auto& item : items) {
                        try {
                            static_cast<void>(inventory_verified_model(item, root));
                            static_cast<void>(inventory_character_parts(&item, root));
                        } catch (const std::exception&) { /* Missing content keeps the normal base-model fallback. */ }
                    }
                });
        }
        if (inventory_view) { consume_inventory_view(); return; }
        InventoryCosmetic crate_preview;
        crate_preview.id="supply-crate-preview";
        const auto* item=inventory_menu.section==InventorySection::crates?&crate_preview:inventory_menu.selected_item();
        const auto key=item && item->kind!="profile_badge"
            ? item->id+":"+std::to_string(inventory_menu.angle)+":"+std::to_string(inventory_menu.zoom)+":"+std::to_string(inventory_menu.blue_team)
            : std::string{};
        if (key!=inventory_preview_key) inventory_menu.preview_ready=false;
        if (inventory_preview_worker.valid() && inventory_preview_worker.wait_for(0ms) == std::future_status::ready) {
            auto result = inventory_preview_worker.get();
            if (result.key==key && !result.error.empty()) inventory_menu.error = std::move(result.error);
            if (result.key==key && !result.pixels.empty()) {
                const auto texture_id = texture_key(inventory_preview_asset, render::TextureFilter::linear);
                const auto existing = image_textures.find(texture_id);
                bool uploaded{};
                if (existing == image_textures.end()) {
                    if (const auto texture = renderer.create_texture_rgba8(result.pixels,
                            {world::cosmetic_preview_width, world::cosmetic_preview_height}, render::TextureFilter::linear)) {
                        image_textures.emplace(texture_id,*texture); uploaded=true;
                    }
                } else uploaded=renderer.update_texture_rgba8(existing->second.texture,result.pixels);
                inventory_menu.preview_ready=uploaded;
            }
        }
        if (inventory_preview_worker.valid() || player_profile_menu.selected_tab()!=PlayerProfileTab::inventory) return;
        if (key.empty()) { inventory_preview_key.clear(); return; }
        if (key==inventory_preview_key) return;
        inventory_preview_key=key; inventory_menu.preview_ready=false;
        inventory_preview_worker=std::async(std::launch::async,[item=*item,root=config.asset_root,key,
                blue=inventory_menu.blue_team,angle=inventory_menu.angle,zoom=inventory_menu.zoom] {
            try { return InventoryPreviewOutcome{key,build_inventory_preview(item,root,blue,angle,zoom),{}}; }
            catch (const std::exception& error) { return InventoryPreviewOutcome{key,{},error.what()}; }
        });
    }

    void launch_profile_request(PlayerProfileRequest request) {
        pending_profile_request.reset();
        const auto service = score_service_config();
        const auto identity = identity_service;
        const auto player_name = config.player_name;
        const auto known_account =
            request.account_id == 0U ? resolved_player_account_id : request.account_id;
        const auto requests_signed_in_profile = known_account != 0U &&
                                                known_account == resolved_player_account_id &&
                                                identity->has_online_session();
        profile_worker = std::async(
            std::launch::async,
            [request,
             service,
             identity,
             player_name,
             known_account,
             requests_signed_in_profile]() mutable {
                auto account_id = known_account;
                std::optional<std::uint64_t> resolved;
                if (requests_signed_in_profile) {
                    return ProfileOutcome{request, identity->own_profile(), std::nullopt};
                }
                if (account_id == 0U) {
                    std::string error;
                    const auto found =
                        network::resolve_aosplay_account_id(service, player_name, error);
                    if (!found.has_value()) {
                        return ProfileOutcome{request, {{}, std::move(error)}, std::nullopt};
                    }
                    account_id = *found;
                    resolved = account_id;
                }
                auto result = network::fetch_aosplay_profile(service, account_id);
                return ProfileOutcome{request, std::move(result), std::move(resolved)};
            });
    }

    void dispatch_profile_request() {
        const auto request = player_profile_menu.take_request();
        if (!request.has_value())
            return;
        if (profile_worker.valid()) {
            pending_profile_request = *request;
            return;
        }
        launch_profile_request(*request);
    }

    void pump_profile_request() {
        using namespace std::chrono_literals;
        if (!profile_worker.valid() || profile_worker.wait_for(0ms) != std::future_status::ready) {
            return;
        }
        auto outcome = profile_worker.get();
        if (outcome.resolved_account_id.has_value()) {
            resolved_player_account_id = *outcome.resolved_account_id;
        }
        if (outcome.result && outcome.result.profile.has_value()) {
            static_cast<void>(player_profile_menu.complete(outcome.request,
                                                           profile_data(*outcome.result.profile)));
        } else {
            if (!outcome.result.error.empty())
                settings_warning = outcome.result.error;
            static_cast<void>(player_profile_menu.fail(outcome.request));
        }
        if (pending_profile_request.has_value()) {
            const auto pending = *pending_profile_request;
            launch_profile_request(pending);
        }
    }

